/**
 * Thai Cultural Context Types
 * KB Expansion Feb 2026
 *
 * Implements types from Knowledge Base sections:
 * - Section 01: Fashion Fundamentals
 * - Section 02: Thai Culture & Fashion
 * - Section 07: Festivals & Holidays
 * - Section 12: Thai Micro-Seasons
 */

import type {
  ThaiDayOfWeek,
  CoverageType,
  WeddingAppropriateType,
  SongkranSuitability,
  ThaiMonth,
} from './enums'

// ============================================================================
// THAI DAY COLOR SYSTEM
// ============================================================================

/**
 * Thai Day Color Mapping
 * Each day of the week has associated lucky and unlucky colors
 * Reference: KB Section 02 - Thai Culture & Fashion
 */
export interface ThaiDayColor {
  day: ThaiDayOfWeek
  luckyColors: string[]
  unluckyColors: string[]
  neutralColors: string[]
}

/**
 * Complete Thai Fortune Color System
 * Maps birth day to auspicious colors for the wearer
 */
export interface ThaiFortuneColors {
  birthDay: ThaiDayOfWeek
  primaryLucky: string      // Main lucky color
  secondaryLucky: string[]  // Additional lucky colors
  avoid: string[]           // Colors to avoid
  neutral: string[]         // Safe neutral colors
}

/**
 * Thai Day Color Database
 * Traditional Thai color associations by day of birth
 */
export const THAI_DAY_COLORS: Record<ThaiDayOfWeek, ThaiDayColor> = {
  sunday: {
    day: 'sunday',
    luckyColors: ['red', 'maroon', 'burgundy'],
    unluckyColors: ['blue', 'navy'],
    neutralColors: ['white', 'cream', 'beige'],
  },
  monday: {
    day: 'monday',
    luckyColors: ['yellow', 'cream', 'ivory'],
    unluckyColors: ['red', 'maroon'],
    neutralColors: ['white', 'gold', 'beige'],
  },
  tuesday: {
    day: 'tuesday',
    luckyColors: ['pink', 'rose', 'light-pink'],
    unluckyColors: ['yellow', 'gold'],
    neutralColors: ['white', 'cream', 'gray'],
  },
  wednesday: {
    day: 'wednesday',
    luckyColors: ['green', 'emerald', 'sage'],
    unluckyColors: ['pink', 'rose'],
    neutralColors: ['white', 'cream', 'brown'],
  },
  thursday: {
    day: 'thursday',
    luckyColors: ['orange', 'brown', 'tan'],
    unluckyColors: ['purple', 'violet'],
    neutralColors: ['white', 'cream', 'beige'],
  },
  friday: {
    day: 'friday',
    luckyColors: ['blue', 'light-blue', 'sky-blue'],
    unluckyColors: ['black', 'dark-gray'],
    neutralColors: ['white', 'cream', 'silver'],
  },
  saturday: {
    day: 'saturday',
    luckyColors: ['purple', 'violet', 'lavender'],
    unluckyColors: ['green', 'emerald'],
    neutralColors: ['white', 'black', 'gray'],
  },
}

// ============================================================================
// THAI CLIMATE CONTEXT
// ============================================================================

/**
 * Coverage Requirements for Cultural Appropriateness
 * Used for temple visits, formal occasions
 */
export interface CoverageRequirements {
  shoulders: CoverageType
  knees: CoverageType
  midriff?: CoverageType
  chest?: CoverageType
}

/**
 * Thai Climate Context Interface
 * Comprehensive Thai cultural and climate appropriateness
 * Reference: KB Sections 02, 07, 12
 */
export interface ThaiClimateContext {
  // --- Climate Suitability ---
  /** Overall suitability for Thai tropical climate (1-10) */
  thaiClimateRating: number
  /** Suitable for air-conditioned environments */
  acFriendly: boolean
  /** Month-by-month suitability scores (1-10), index 0 = January */
  monthSuitability: number[]

  // --- Cultural Appropriateness ---
  /** Appropriate for temple visits */
  templeAppropriate: boolean
  /** Wedding guest appropriateness */
  weddingAppropriate: WeddingAppropriateType
  /** Funeral appropriateness (black required) */
  funeralAppropriate: boolean

  // --- Festival Suitability ---
  /** Songkran (Thai New Year) suitability */
  songkranSuitable: SongkranSuitability
  /** Loy Krathong suitability */
  loyKrathongSuitable: boolean

  // --- Coverage for Cultural Settings ---
  /** Body coverage for temple/formal compliance */
  coverage: CoverageRequirements

  // --- Thai Day Colors ---
  /** Days this color is auspicious for */
  thaiDayColors?: ThaiDayOfWeek[]
}

// ============================================================================
// THAI CALENDAR EVENTS
// ============================================================================

/**
 * Thai Calendar Event
 * Important dates that affect fashion choices
 */
export interface ThaiCalendarEvent {
  name: string
  nameThai: string
  month: ThaiMonth
  day?: number
  colorRequired?: string
  colorRecommended?: string[]
  dressCode?: string
}

/**
 * Major Thai Events with Fashion Implications
 * Reference: KB Section 07, 12
 */
export const THAI_CALENDAR_EVENTS: ThaiCalendarEvent[] = [
  {
    name: "New Year's Day",
    nameThai: 'วันขึ้นปีใหม่',
    month: 1,
    day: 1,
    colorRecommended: ['white', 'gold', 'red'],
  },
  {
    name: 'Makha Bucha Day',
    nameThai: 'วันมาฆบูชา',
    month: 2,
    colorRecommended: ['white', 'cream'],
    dressCode: 'temple-appropriate',
  },
  {
    name: 'Songkran',
    nameThai: 'วันสงกรานต์',
    month: 4,
    day: 13,
    colorRecommended: ['white', 'floral', 'bright-colors'],
  },
  {
    name: 'Coronation Day',
    nameThai: 'วันฉัตรมงคล',
    month: 5,
    day: 4,
    colorRequired: 'yellow',
  },
  {
    name: "Queen's Birthday / Mother's Day",
    nameThai: 'วันแม่แห่งชาติ',
    month: 8,
    day: 12,
    colorRequired: 'light-blue',
  },
  {
    name: 'King Rama IX Memorial Day',
    nameThai: 'วันคล้ายวันสวรรคต ร.9',
    month: 10,
    day: 13,
    colorRequired: 'black',
  },
  {
    name: "King's Birthday / Father's Day",
    nameThai: 'วันพ่อแห่งชาติ',
    month: 12,
    day: 5,
    colorRequired: 'yellow',
  },
  {
    name: 'Loy Krathong',
    nameThai: 'วันลอยกระทง',
    month: 11,
    colorRecommended: ['traditional-thai', 'pastel', 'elegant'],
    dressCode: 'smart-casual-to-elegant',
  },
]

// ============================================================================
// HELPER FUNCTIONS
// ============================================================================

/**
 * Get lucky colors for a specific day of the week
 * @param day - Day of week
 * @returns Array of lucky colors
 */
export function getLuckyColorsForDay(day: ThaiDayOfWeek): string[] {
  return THAI_DAY_COLORS[day].luckyColors
}

/**
 * Check if a color is lucky for a specific day
 * @param color - Color to check
 * @param day - Day of week
 * @returns true if color is lucky
 */
export function isLuckyColorForDay(color: string, day: ThaiDayOfWeek): boolean {
  const normalizedColor = color.toLowerCase().replace(/\s+/g, '-')
  return THAI_DAY_COLORS[day].luckyColors.some(
    (c) => c.toLowerCase() === normalizedColor
  )
}

/**
 * Check if a color should be avoided for a specific day
 * @param color - Color to check
 * @param day - Day of week
 * @returns true if color should be avoided
 */
export function shouldAvoidColorForDay(color: string, day: ThaiDayOfWeek): boolean {
  const normalizedColor = color.toLowerCase().replace(/\s+/g, '-')
  return THAI_DAY_COLORS[day].unluckyColors.some(
    (c) => c.toLowerCase() === normalizedColor
  )
}

/**
 * Get the required color for a specific month (if any)
 * @param month - Month number (1-12)
 * @returns Required color or undefined
 */
export function getRequiredColorForMonth(month: ThaiMonth): string | undefined {
  const event = THAI_CALENDAR_EVENTS.find(
    (e) => e.month === month && e.colorRequired
  )
  return event?.colorRequired
}

/**
 * Check if an outfit is temple-appropriate based on coverage
 * @param coverage - Coverage requirements of the outfit
 * @returns true if temple-appropriate
 */
export function isTempleAppropriate(coverage: CoverageRequirements): boolean {
  return coverage.shoulders === 'covered' && coverage.knees === 'covered'
}

/**
 * Get Thai fortune colors for a birth day
 * @param birthDay - Day of week born on
 * @returns Fortune color recommendations
 */
export function getThaiFortuneColors(birthDay: ThaiDayOfWeek): ThaiFortuneColors {
  const dayColors = THAI_DAY_COLORS[birthDay]
  return {
    birthDay,
    primaryLucky: dayColors.luckyColors[0],
    secondaryLucky: dayColors.luckyColors.slice(1),
    avoid: dayColors.unluckyColors,
    neutral: dayColors.neutralColors,
  }
}

/**
 * AI Matching Types
 * KB Expansion Feb 2026
 *
 * Implements types from Knowledge Base sections:
 * - Section 15: Visual Matching Intelligence
 * - Section 16: Outfit Composition Rules
 * - Section 17: Cross-Product Compatibility
 * - Section 13: Price Intelligence
 * - Special Topics: Social Proof Signals
 */

import type {
  SilhouetteShape,
  VisualWeightLevel,
  ProportionRatio,
  TextureType,
  OutfitRoleType,
  ProductRelationship,
  TrendLifecycle,
  PopularityTier,
  CostPerWearTier,
  SaleLikelihood,
  OutfitCompleteness,
  LayerCompatibility,
} from './enums'

// ============================================================================
// VISUAL MATCHING INTELLIGENCE (KB Section 15)
// ============================================================================

/**
 * Proportion Effect
 * How a garment affects perceived body proportions
 */
export interface ProportionEffect {
  /** Effect on perceived torso length (-5 to +5) */
  torsoLengthening: number
  /** Effect on perceived leg length (-5 to +5) */
  legLengthening: number
  /** Effect on perceived height (-5 to +5) */
  heightEffect: number
  /** Effect on perceived width (-5 to +5) */
  widthEffect: number
}

/**
 * Visual Matching Attributes Interface
 * For AI-powered image-to-product matching
 * Reference: KB Section 15 - Visual Matching Intelligence
 */
export interface VisualMatchingAttributes {
  /** Overall silhouette shape (A-line, H-line, etc.) */
  silhouetteShape: SilhouetteShape

  /** Visual weight score (1-10, 1=airy, 10=heavy) */
  visualWeightScore: number

  /** Visual weight category */
  visualWeightLevel: VisualWeightLevel

  /** Where visual weight is concentrated */
  proportionRatio: ProportionRatio

  /** How garment affects body proportions */
  proportionEffect: ProportionEffect

  /** Pattern complexity score (1-10, 1=solid, 10=complex) */
  patternComplexity: number

  /** Surface texture type */
  textureType: TextureType

  /** Role in outfit composition */
  outfitRoleType: OutfitRoleType

  /** Suitability for Thai body proportions (1-10) */
  thaiProportionScore: number

  /** Can serve as statement piece */
  statementPotential: boolean

  /** Mood/vibe keywords */
  styleMoods: string[]
}

// ============================================================================
// CROSS-PRODUCT COMPATIBILITY (KB Section 17)
// ============================================================================

/**
 * Cross-Product Compatibility Interface
 * For product-to-product pairing recommendations
 * Reference: KB Section 17 - Cross-Product Compatibility Matrix
 */
export interface CrossProductCompatibility {
  /** Overall pairing compatibility score (0-100) */
  pairingScore: number

  /** Required companion categories (e.g., 'bottom' for tops) */
  essentialPairings: string[]

  /** Categories/styles to avoid pairing with */
  avoidPairings: string[]

  /** Versatility score (1-10, how many outfits possible) */
  versatilityScore: number

  /** Compatible layering styles */
  layerCompatibility: LayerCompatibility[]

  /** What's needed to complete outfit */
  outfitCompleteness: OutfitCompleteness

  /** Formality tolerance for pairing (±range) */
  formalityTolerance: number

  /** Safe to mix with patterns */
  patternMixingSafe: boolean

  /** SKUs of perfect match products */
  perfectMatchSkus: string[]

  /** Relationship type with commonly paired items */
  commonPairings?: Array<{
    sku: string
    relationship: ProductRelationship
    score: number
  }>
}

// ============================================================================
// PRICE INTELLIGENCE (KB Section 13)
// ============================================================================

/**
 * Price Intelligence Interface
 * For value-based shopping recommendations
 * Reference: KB Section 13 - Price Intelligence
 */
export interface PriceIntelligence {
  /** Calculated cost per wear (price ÷ expected wears) */
  costPerWear: number

  /** Cost per wear tier classification */
  costPerWearTier: CostPerWearTier

  /** Investment value score (0-100) */
  investmentScore: number

  /** Quality tier (1-5) */
  qualityTier: 1 | 2 | 3 | 4 | 5

  /** Timelessness score (1-10, 10=never goes out of style) */
  timelessScore: number

  /** Qualifies as investment piece */
  isInvestmentPiece: boolean

  /** Suitable for capsule wardrobe */
  isCapsuleWardrobe: boolean

  /** How often this goes on sale */
  saleLikelihood: SaleLikelihood

  /** Best time to purchase */
  bestPurchaseTiming: string

  /** Expected number of wears */
  expectedWears?: number

  /** Value tier (quality relative to price) */
  valueTier?: 'exceptional' | 'fair' | 'premium' | 'overpriced'
}

// ============================================================================
// SOCIAL PROOF SIGNALS (Special Topics)
// ============================================================================

/**
 * Influencer Feature
 * Tracking influencer/celebrity wearing this item
 */
export interface InfluencerFeature {
  name: string
  platform: 'instagram' | 'tiktok' | 'youtube' | 'pinterest' | 'celebrity'
  date?: string
  url?: string
}

/**
 * Social Proof Signals Interface
 * For popularity and trend-based recommendations
 * Reference: KB Special Topics - Social Proof Signals
 */
export interface SocialProofSignals {
  /** Overall popularity score (0-100) */
  popularityScore: number

  /** Popularity tier classification */
  popularityTier: PopularityTier

  /** Current trend lifecycle stage */
  trendStatus: TrendLifecycle

  /** Confidence in trend assessment (0-100) */
  trendConfidence: number

  /** Celebrity/influencer associations */
  celebrityAssociations: string[]

  /** Trending hashtags associated with this item */
  hashtagTrending: string[]

  /** Average review sentiment (0-100, 100=positive) */
  reviewSentiment: number

  /** Total review count */
  reviewCount: number

  /** Recommendation rate (% who would recommend) */
  recommendRate: number

  /** Number of influencer features */
  influencerFeatures: number

  /** Detailed influencer features */
  influencerDetails?: InfluencerFeature[]

  /** Sales velocity indicator */
  salesVelocity?: 'fast-selling' | 'steady' | 'slow'

  /** Stock scarcity signal */
  stockScarcity?: 'limited' | 'available' | 'abundant'
}

// ============================================================================
// OUTFIT COMPOSITION (KB Section 16)
// ============================================================================

/**
 * Outfit Formula Component
 * Single piece in an outfit formula
 */
export interface OutfitFormulaComponent {
  role: OutfitRoleType
  category: string
  required: boolean
  alternatives?: string[]
}

/**
 * Outfit Formula
 * Complete look formula for specific occasions
 * Reference: KB Section 16 - Outfit Composition Rules
 */
export interface OutfitFormula {
  name: string
  occasion: string
  formalityRange: [number, number]
  components: OutfitFormulaComponent[]
  colorRules?: string[]
  budgetAllocation?: Record<string, number>
  thaiClimateNotes?: string
}

/**
 * Anchor Piece Rules
 * Rules for the main/focal piece of an outfit
 */
export interface AnchorPieceRules {
  /** Only one anchor per outfit */
  maxAnchorPieces: 1
  /** Only one statement per outfit */
  maxStatementPieces: 1
  /** Categories that can serve as anchor */
  anchorCategories: string[]
}

// ============================================================================
// COMPOSITE TYPES
// ============================================================================

/**
 * Complete AI Matching Profile
 * All AI matching attributes for a product
 */
export interface AIMatchingProfile {
  visualMatching: VisualMatchingAttributes
  crossProductCompatibility: CrossProductCompatibility
  priceIntelligence: PriceIntelligence
  socialProof: SocialProofSignals
}

/**
 * Product Match Result
 * Result of matching a look inspiration to products
 */
export interface ProductMatchResult {
  productSku: string
  matchScore: number
  matchReasons: string[]
  relationship: ProductRelationship
  visualSimilarity: number
  styleSimilarity: number
  pricingMatch: boolean
}

/**
 * Look-to-Product Match Request
 * Input for AI look matching
 */
export interface LookMatchRequest {
  lookDescription: string
  occasion?: string
  budget?: { min: number; max: number }
  preferredBrands?: string[]
  excludeBrands?: string[]
  mustHaveFeatures?: string[]
  avoidFeatures?: string[]
}

